/**
 * Missão estabilização 2026-10-22 — mixin do totals de frete (KO).
 * Adiciona isACombinar() aos componentes de totals de frete do Magento_Tax
 * (summary do checkout OPC + totals do carrinho) para o template override
 * exibir "A combinar" no lugar de "R$ 0,00" quando o método é o CarrierSelect.
 */
define([], function () {
    'use strict';

    return function (Component) {
        return Component.extend({
            /**
             * O frete é "a combinar" quando o título do método selecionado
             * contém "combinar" (CarrierSelect seta preço 0 por design).
             *
             * @return {boolean}
             */
            isACombinar: function () {
                var title = '';

                if (typeof this.getShippingMethodTitle === 'function') {
                    title = String(this.getShippingMethodTitle() || '');
                } else if (typeof this.getShippingDescription === 'function') {
                    title = String(this.getShippingDescription() || '');
                }

                return /combinar/i.test(title);
            }
        });
    };
});
